// The TypeScript types of Clank's kinds of record, as the API sends them (decisions 0015, 0028).
// Generated by `uv run python -m tools.tstypes` from each kind's one definition: never edit this file by hand.

/** How the Clank service runs. */
export interface ServiceSettings {
  /** The name clients show for this record; the file's own name when empty. */
  title: string;
  /** The address the API listens on; 127.0.0.1 keeps it to this machine (design 0002 §2.7). */
  host: string;
  /** The TCP port the API listens on. */
  port: number;
  /** How many days events are kept before they are pruned. */
  events_kept_days: number;
}

/** How the console looks (design 0011 §3). */
export interface ConsoleSettings {
  /** The name clients show for this record; the file's own name when empty. */
  title: string;
  /** The style the console draws in, by its file's name. */
  style: string;
  /** The size of the Flow view's boxes: small, medium or large (+ and - on the Flow view change it); a panel too narrow for two of them draws the largest that fits two. */
  flow_boxes: "small" | "medium" | "large";
}

/** A style of the console: every element of its look, by name (design 0011 §2). */
export interface StyleSettings {
  /** The name clients show for this record; the file's own name when empty. */
  title: string;
  /** Whether the style is dark, for the widgets Textual draws. */
  dark: boolean;
  /** The colors by role, what each is for. */
  colors: StyleColors;
  /** Six colors in order, for the series of a chart; a sparkline takes the first. */
  data: string[];
  /** The colors the Monitor and flows draw kinds in. */
  kinds: StyleKinds;
  /** A panel's border: square corners, or round. */
  border: "solid" | "round";
  /** A panel's title. */
  titles: StyleTitles;
  /** The glyphs that say a state. */
  marks: StyleMarks;
  /** The spinner's frames, while something runs. */
  spinner: string;
  bar: StyleBar;
  /** A sparkline's steps, from none to the most. */
  sparks: string;
  /** A branching flow's connectors. */
  tree: StyleTree;
  /** The room between things. */
  spacing: StyleSpacing;
}

/** Something that happened. */
export interface Event {
  /** A number that only grows; none for a live-only event. */
  id: number | null;
  /** When it happened, in UTC. */
  time: string;
  /** What happened, such as question.asked (docs/EVENTS.md lists them). */
  type: string;
  /** The record it concerns, if any. */
  subject: Subject | null;
  /** Who caused it. */
  actor: Actor;
  /** What happened, in one line of plain English. */
  summary: string;
  /** The fields its type declares; large content is referenced. */
  data: Record<string, unknown>;
  /** Whether it needs the owner's attention, as its type declares (decision 0113): a client may notify, with the summary as its title. */
  attention: boolean;
}

/** Something slow that runs in the service, step by step. */
export interface Operation {
  /** The operation's name, such as op-1f2e3d4c. */
  id: string;
  /** The kind of operation, such as docker.stop. */
  type: string;
  /** What it does, in a few words. */
  title: string;
  /** queued, running, waiting (for the user), done, failed, canceled or interrupted. */
  status: "queued" | "running" | "waiting" | "done" | "failed" | "canceled" | "interrupted";
  /** Who started it, and through which client. */
  started_by: Actor;
  /** When it was started. */
  created: string;
  /** When it last changed. */
  updated: string;
  /** When it ended. */
  finished: string | null;
  /** Whether the user can stop it while it runs. */
  cancelable: boolean;
  /** What it was asked to do. */
  params: Record<string, unknown>;
  /** What it produced, once done. */
  result: Record<string, unknown> | null;
  /** Why it failed, was canceled, or was interrupted. */
  error: string;
  /** The key of the request that started it; the same key starts no other. */
  request_key: string | null;
  /** What it holds while it runs. */
  locks: string[];
  /** The question it waits for, if any. */
  waiting_on: string | null;
  /** How many steps its kind declares. */
  planned_steps: number;
  /** The steps it has run so far. */
  steps: Step[];
  /** The operation it tries again, if any. */
  retry_of: string | null;
}

/** A question to the user, and its answer once there is one. */
export interface Question {
  /** approval: may this happen?; choice: one of these; text: an answer in words, with suggestions. */
  type: "approval" | "choice" | "text";
  /** The question in one line. */
  title: string;
  /** Exactly what is at stake: the command, the diff, the host, the reason. */
  detail: string;
  /** Each possible answer and what it does; for a text question, suggested answers. */
  options: Option[];
  /** The option taken if nobody answers in time. */
  default: string | null;
  /** When the default is taken if nobody has answered. */
  expires: string | null;
  /** How soon the user should see it; high ones reach the phone at once. */
  urgency: "normal" | "high";
  /** The record the question concerns. */
  about: Subject | null;
  /** The question's name, such as q-7f3a91. */
  id: string;
  /** waiting for an answer, answered, expired (its default taken), or withdrawn. */
  status: "waiting" | "answered" | "expired" | "withdrawn";
  /** Who asks. */
  asked_by: Actor;
  /** When it was asked. */
  asked: string;
  /** The answer, once there is one. */
  answer: Answer | null;
  /** Why it was withdrawn. */
  reason: string;
  /** The operation waiting for the answer. */
  operation_id: string | null;
}

/** What Clank detected about this computer. */
export interface MachineProfile {
  /** The name clients show for this record; the file's own name when empty. */
  title: string;
  /** The operating system and its version. */
  system: string;
  /** The version of Python that runs Clank. */
  python: string;
  /** On Windows, WSL's version and default distribution, or not installed. */
  wsl: string;
  /** The processor's model. */
  processor: string;
  /** The processor's physical cores. */
  cores: number;
  /** The computer's memory, in gibibytes. */
  memory_gb: number;
  /** The NVIDIA GPUs found. */
  gpus: Gpu[];
  /** The version of the Docker command, or not installed. */
  docker: string;
  /** When Clank last detected all this. */
  detected: string | null;
}

/** How Clank uses Docker. */
export interface DockerSettings {
  /** The name clients show for this record; the file's own name when empty. */
  title: string;
  /** The adapter Clank uses for containers: auto (Docker Desktop on Windows and macOS; on Linux, the one of the engine the docker command would use, chosen without waking any: Docker's view says which and why), docker-desktop, or docker-engine (Docker Engine on Linux, the system's service, which Clank never starts or stops). */
  adapter: string;
  /** How often, in seconds, Clank reads Docker's state. */
  poll_seconds: number;
  /** Open workspaces even where Docker cannot limit a container's memory (a Raspberry Pi's default kernel): an agent's runaway process could then take this computer's memory. Off: no workspace opens there, saying how to turn the limits on. */
  allow_unlimited_memory: boolean;
  /** How long a start may take before it is reported as failed. */
  start_timeout_seconds: number;
  /** How long a stop may take before it is reported as failed. */
  stop_timeout_seconds: number;
  /** How long a question about stopping Docker waits before its default (cancel) applies. */
  question_minutes: number;
}

/** A folder an agent works in, in a container of its own. */
export interface Workspace {
  /** The name clients show for this record; the file's own name when empty. */
  title: string;
  /** The folder on this machine; its container sees it as /workspace, and nothing else of the machine. */
  path: string;
  /** The CPUs its container may use; empty: half of what Docker has. */
  cpus: number | null;
  /** The memory its container may use, in MiB; empty: a quarter of what Docker has. */
  memory_mib: number | null;
  /** What its container has besides Clank's sandbox image, each built on it once: tex (TeX Live, for the LaTeX the agent writes, design 0020). Its container moves to the new image when it is next made. */
  layers: string[];
  /** The command that installs the folder's own software into its home (~/.venv), run by Clank in a container that reaches the internet; empty: proposed from the folder's files (pyproject.toml, requirements.txt). */
  setup: string | null;
  /** The setup command that last ran to its end; empty: the software is not installed. */
  set_up: string;
  /** The folder's own MCP servers (its .mcp.json) its agent gets, each with the fingerprint of its entry as allowed: an entry changed since is not given until it is allowed again. */
  mcp_allowed: Record<string, string>;
  /** Your own MCP servers (clank mcp add) this workspace's agent does not get; the others it gets. */
  mcp_off: string[];
  /** The internet hosts its agent reaches through Clank's proxy (design 0024): a name (pypi.org) or a suffix (.arxiv.org: arxiv.org and every name under it), each with when and how it was allowed. Every other host is refused; private addresses always. */
  hosts: Record<string, string>;
  /** review: the agent asks before it changes a file, and you accept or reject the change (VS Code shows it beside your files); auto: it changes files without asking, and VS Code shows each change after. */
  changes: "review" | "auto";
  /** Opening OpenCode in a terminal (VS Code's, or the console's) first closes every OpenCode window open in the workspace, so there is only ever one and switching between plan, review and auto reaches it; off: each opening adds another window. OpenCode without a terminal (the phone's) is left alone. */
  one_window: boolean;
  /** this-machine: its agent's requests go only to a model on this machine; cloud: also to a cloud model, once you allowed it (design 0016 §9). Every workspace starts on this machine. */
  models: "this-machine" | "cloud";
  /** When you last answered whether it may use the cloud model; empty: never asked, or not answered in time, so it is asked the next time a cloud model would serve it. */
  cloud_answered: string;
}

/** A saved launch configuration. */
export interface Preset {
  /** The name clients show for this record; the file's own name when empty. */
  title: string;
  /** The engine adapter that runs it, such as kvmem-llamacpp; empty for a cloud preset. */
  engine: string;
  /** The engine's version, such as v0.16.0-rc1; empty for a cloud preset. */
  engine_version: string;
  /** For a cloud preset, in place of an engine: the provider someone else runs that serves its model (config/endpoints/<id>.json), such as openrouter (design 0016 §7). */
  endpoint: string;
  /** The model's id in the catalog, such as qwen3.8-27b; for a cloud preset, its id exactly as its provider lists it. */
  model: string;
  /** The options that differ from the engine's defaults, by their keys (design 0001 §3.1); for a cloud preset: context, max_output, reasoning and images. */
  options: Record<string, number | number | string | boolean>;
  /** The slot it is for (design 0001 §1). */
  slot: string;
  /** Where it runs; empty: the one host its engine is installed on (decision 0030). */
  host: string;
  /** Anything worth knowing: where it came from, what it deviates in. */
  notes: string;
  /** A preset the slot loads when this one's engine crashes (settings on trial, design 0021 §10); empty: the crash rule every preset has (started again once, or asked). */
  fallback: string;
}

/** Where engines run. */
export interface Host {
  /** The name clients show for this record; the file's own name when empty. */
  title: string;
  /** wsl: a WSL distribution, through wsl.exe; local: the service's own Linux. */
  adapter: "wsl" | "local";
  /** For wsl: the distribution's name, such as Ubuntu-22.04. */
  distro: string;
  /** The folder on the host that holds its engines and models. */
  clank_folder: string;
}

/** Where a model's file is on a host, outside the host's own models folder. */
export interface ModelFile {
  /** The name clients show for this record; the file's own name when empty. */
  title: string;
  /** The model's id in the catalog. */
  model: string;
  /** The file's name, as the catalog lists it. */
  file: string;
  /** The host the file is on. */
  host: string;
  /** Where it is on that host. */
  path: string;
}

/** How the runtime runs its engines. */
export interface RuntimeSettings {
  /** The name clients show for this record; the file's own name when empty. */
  title: string;
  /** The seats for models: main for the agent's, fast for completion (design 0006), vision for the model that reads images on the CPU (design 0008). */
  slots: string[];
  /** Where an engine listens, until the gateway takes this port (design 0001 §9.2). */
  port: number;
  /** A port of its own for a slot whose engine runs beside another; the rest take the engines' port. */
  ports: Record<string, number>;
  /** The model name the gateway puts in each request it passes to the engine; empty: the model's id in Clank's catalog. */
  model_name: string;
  /** A fit with less spare GPU memory than this, in MiB, is tight. */
  tight_mib: number;
  /** How long an engine may take to be ready, in seconds. */
  start_seconds: number;
  /** How often a running engine is asked. */
  health_seconds: number;
  /** How often a cloud model's provider is asked whether it still takes the key (it costs nothing). */
  cloud_health_seconds: number;
  /** What clank work, clank code and This folder load when the main slot runs nothing and no configuration has worked yet (design 0015 §13). */
  fallback_preset: string;
  /** For testing (decisions 0149 and 0152): while on, every cloud provider is asked for any of a model's providers (data_collection allow), those that may keep or train on what they are sent too, whatever its own record says, from the next request; and every workspace's agent reaches every public host at once, without a question (private addresses still never), OpenCode fetching and searching the web from its next start. The console's header says so. clank dev on, clank dev off. */
  dev_mode: boolean;
}

/** A provider someone else runs, reached at its URL with the owner's key (design 0016 §4). */
export interface Endpoint {
  /** The name clients show for this record; the file's own name when empty. */
  title: string;
  /** The endpoint adapter that speaks to it, such as openrouter. */
  adapter: string;
  /** Its API's base URL; for a cloud provider the adapter's own, so the key never goes elsewhere. */
  url: string;
  /** bearer: the key in an Authorization header; none: no key. */
  auth: "bearer" | "none";
  /** Where what it is sent goes: this-machine, my-servers, or cloud (a company's API). */
  reach: "this-machine" | "my-servers" | "cloud";
  /** The adapter's own options, such as OpenRouter's data_collection (deny: only providers that keep no data) and zdr (only zero-data-retention providers). */
  options: Record<string, number | number | string | boolean>;
  /** When you agreed that prompts and the files and command output the agent reads go to it; empty: not agreed, and nothing loads from it. */
  agreed: string;
  /** The longest the gateway waits for the next piece of an answer, in seconds. */
  timeout_seconds: number;
  /** Anything worth knowing. */
  notes: string;
}

/** What a slot runs now. */
export interface SlotRecord {
  /** The slot, such as main. */
  name: string;
  /** stopped, starting, ready, stopping or failed. */
  status: "stopped" | "starting" | "ready" | "stopping" | "failed";
  /** When it reached that state. */
  since: string;
  /** Why it is in that state. */
  reason: string;
  /** The preset it runs or starts. */
  preset: string | null;
  /** The launch that runs now. */
  launch_id: number | null;
  /** Where its engine runs. */
  host: string | null;
  /** Its engine's process id on that host. */
  pid: number | null;
  /** Its process's start time, as its host says. */
  started: string | null;
  /** The SHA-256 of its process's command line. */
  command: string | null;
  /** Where its engine listens. */
  port: number | null;
  /** The last configuration that worked. */
  last_good: LastGood | null;
}

/** One start of an engine. */
export interface LaunchRecord {
  /** Its number. */
  id: number;
  /** The slot it was for. */
  slot: string;
  /** The preset it started. */
  preset: string;
  /** The preset's options then. */
  options: Record<string, unknown>;
  /** The engine adapter. */
  engine: string;
  /** The engine's version. */
  engine_version: string;
  /** Where it ran. */
  host: string;
  /** Exactly what ran, its environment first. */
  command_line: string;
  /** Where its output went. */
  log: string;
  /** When it was started. */
  started_at: string;
  /** When it was ready. */
  ready_at: string | null;
  /** When it ended. */
  ended_at: string | null;
  /** starting, ready, failed, stopped or crashed. */
  outcome: "starting" | "ready" | "failed" | "stopped" | "crashed";
  /** Why it failed or ended, in the engine's words. */
  detail: string;
  /** The GPU memory it was expected to take, MiB. */
  estimate_mib: number | null;
  /** The GPU memory in use before it started, MiB. */
  before_mib: number | null;
  /** The GPU memory it took once ready, MiB. */
  measured_mib: number | null;
  /** The GPU memory it needed free to start, MiB, when its engine says (one that reserves extra). */
  needed_mib: number | null;
  /** From its start to ready, in seconds. */
  seconds: number | null;
  /** For a cloud preset's launch: the provider it reached; empty for an engine's. */
  endpoint: string;
  /** For a cloud preset's launch: the route it gave the gateway (never a key). */
  route: Record<string, unknown> | null;
  /** What its own requests cost, in US dollars (a cloud launch's tiny request). */
  cost_usd: number | null;
}

/** An engine installed on a host. */
export interface InstallRecord {
  /** The engine adapter it is for. */
  setup: string;
  /** The engine's version. */
  version: string;
  /** Where it is. */
  host: string;
  /** The command that runs it. */
  program: string[];
  /** Its folder, where it runs. */
  folder: string;
  /** Its libraries' folders, for LD_LIBRARY_PATH. */
  library_path: string;
  /** adopted: found where it was; recipe: built or installed by Clank; test: a fake. */
  how: "adopted" | "recipe" | "test";
  /** Where it came from: a commit, a release, a deviation. */
  detail: string;
  /** When Clank recorded it. */
  installed: string | null;
}

/** How the gateway runs. */
export interface GatewaySettings {
  /** The name clients show for this record; the file's own name when empty. */
  title: string;
  /** Start the gateway when the service starts, and again whenever it is found not running. */
  start: boolean;
  /** Where tools reach the gateway, on this machine only. */
  port: number;
  /** Where the agent's internet requests enter Clank's proxy (design 0024), on this machine only; the edge forwards it to the containers. */
  proxy_port: number;
  /** On Linux, the folder of the gateway's socket and the proxy's, the edge's way to them on Docker Engine (design 0014 §3): the owner's alone, outside CLANK_HOME. Empty: ~/.cache/clank/<home id> (under $XDG_CACHE_HOME when that is set). */
  socket_folder: string;
  /** How long a request waits, in seconds, for a slot that is starting or switching, before refusal. */
  hold_seconds: number;
  /** Answer OpenCode's session-title requests in the gateway, so they never take the place of the conversation the engine keeps cached (design 0001 §6.4). */
  local_titles: boolean;
  /** Stop an answer that repeats itself: the engine stops writing it, and the stream ends with an error that says what repeated (design 0004 §2). A change applies when the gateway restarts: clank gateway restart. */
  loop_guard: boolean;
  /** The stretches of the thinking and the text that the loop guard reads, their newest characters: a short one finds a short repeat soon, a long one prose said again every 600 to 800 characters. */
  loop_windows: number[];
  /** The stretches of a tool call's arguments that the loop guard reads: the short one only, since a file written from a template (records that differ by an id, rows of a table) compresses over a long stretch as far as a loop does. */
  loop_tool_windows: number[];
  /** A part repeats itself when a stretch compresses to under this share of its size (real answers stay above 0.18; the measurement of 2026-10-18). */
  loop_ratio: number;
  /** Keep each request and its answer in logs/traffic. */
  records: boolean;
  /** The longest text kept of one field of a request or answer, in KiB. */
  record_limit_kib: number;
  /** How many days of requests are kept. */
  keep_days: number;
  /** How many days of the agent's internet exchanges are kept (logs/network, design 0024 §4). */
  network_days: number;
}

/** How completion in VS Code works (design 0006 §5-§6). */
export interface CompletionSettings {
  /** The name clients show for this record; the file's own name when empty. */
  title: string;
  /** Suggest the rest of the line as you type in VS Code; off: nothing is asked. */
  enabled: boolean;
  /** How long, in milliseconds, VS Code waits after you stop typing before it asks for a suggestion. */
  delay_ms: number;
  /** one: the rest of the line; few: also a few lines on an empty line after one that opens a block (ending with :, {, ( or [). */
  lines: "one" | "few";
}

/** The model that reads images on the CPU, in the vision slot (design 0008 §7). */
export interface VisionSettings {
  /** The name clients show for this record; the file's own name when empty. */
  title: string;
  /** off: no image is read (annotations go as words, the agent's model is told it takes text only); on-demand: loaded when an image is to be read, unloaded when idle; always: loaded and kept. */
  mode: "off" | "on-demand" | "always";
  /** Minutes without use after which an on-demand model is unloaded. */
  idle_minutes: number;
  /** The preset the vision slot loads. */
  preset: string;
}

/** The cloud's spending limits (design 0016 §11, decision 0104). */
export interface CostSettings {
  /** The name clients show for this record; the file's own name when empty. */
  title: string;
  /** What the cloud may cost in a day, in US dollars; empty: no limit. */
  day_usd: number | null;
  /** What the cloud may cost in a month, in US dollars; empty: no limit. */
  month_usd: number | null;
  /** The share of a limit at which you are told once, such as 0.8. */
  warn_at: number;
}

/** An MCP server added for the user. */
export interface McpServer {
  /** The name clients show for this record; the file's own name when empty. */
  title: string;
  /** How Clank talks to it: stdio, a program started and spoken to over its input and output; http, the streamable HTTP transport; sse, the older server-sent events one. */
  transport: "stdio" | "http" | "sse";
  /** The program that starts it (stdio). */
  command: string;
  /** What the program is given after its name (stdio). */
  args: string[];
  /** The names of the environment variables it is started with; their values are secrets. */
  env: string[];
  /** Where it listens (http, sse). */
  url: string;
  /** The names of the HTTP headers sent to it; their values are secrets. */
  headers: string[];
  /** What it gives the agent never goes to a cloud model (design 0016 §10): a workspace allowed the cloud does not get it, and the gateway keeps its tools and a session that used it from the cloud. */
  local_only: boolean;
}

/** Clank's VS Code window: the program, the extensions it has besides Clank's, and this PC's SSH name. */
export interface VsCodeSettings {
  /** The name clients show for this record; the file's own name when empty. */
  title: string;
  /** VS Code's command line and any arguments before VS Code's own; empty: `code` found on the PATH (on Windows, the program its code.cmd runs). */
  program: string[];
  /** The extensions installed in the window when missing, by their marketplace ids (publisher.name), besides Clank's own: Python, Pylance, the debugger, Ruff, Jupyter, Lean 4, LaTeX Workshop, a PDF viewer, Rainbow CSV, Markdown All in One, Mermaid and Even Better TOML. */
  extensions: string[];
  /** This PC's name in the SSH configuration of the computer you work from (design 0018 §8): over SSH, outside VS Code's Remote-SSH, Clank says the command that opens a folder there with it; empty: the address the SSH session came in on. */
  ssh_host: string;
}

/** What each of the Monitor's Watch for rules does when it fires (design 0012 §8, decision 0053). */
export interface MonitorSettings {
  /** The name clients show for this record; the file's own name when empty. */
  title: string;
  /** When: an approval or a question waits. By default: mark, tell the phone; a key left out keeps its default. */
  waiting_for_you: RuleSettings;
  /** When: the last request ended in the engine's error. By default: mark; a key left out keeps its default. */
  engine_broke_off: RuleSettings;
  /** When: a request ended model_looped. By default: mark, tell the model; a key left out keeps its default. */
  loop_guard_stopped: RuleSettings;
  /** When: a step's answer reached the output limit before it ended (OpenCode's finish, length): a model's thinking counts against the limit, and OpenCode ends the run there (e on the Presets page raises a cloud model's). By default: mark, tell the model; a key left out keeps its default. */
  answer_cut: RuleSettings;
  /** When: OpenCode asks about the same call made again (its doom_loop ask); unanswered, it stalls a run left alone. By default: mark, tell the phone; a key left out keeps its default. */
  asks_about_a_repeat: RuleSettings;
  /** When: the same call three times or more in the last 12. By default: mark; a key left out keeps its default. */
  same_call_again: RuleSettings;
  /** When: four failures or more in the last 8 calls. By default: mark; a key left out keeps its default. */
  failing_again: RuleSettings;
  /** When: one file edited six times or more in the last 30 calls. By default: mark; a key left out keeps its default. */
  one_file_again: RuleSettings;
  /** When: a step ended in an error after one of its calls had started: the file may have changed, and the model is not told. By default: mark; a key left out keeps its default. */
  call_then_step_failed: RuleSettings;
  /** When: the session stopped while an ask waits: the ask stays, and a later answer could still let it run. By default: mark; a key left out keeps its default. */
  stopped_with_an_ask_waiting: RuleSettings;
  /** When: a note was stored, and the run ended without reading it. By default: mark; a key left out keeps its default. */
  note_not_read: RuleSettings;
  /** When: OpenCode tries a request again, attempt n of at most 5. By default: mark; a key left out keeps its default. */
  retrying: RuleSettings;
  /** When: the next step would likely pass the compaction line, at the last steps' pace. By default: mark; a key left out keeps its default. */
  compaction_near: RuleSettings;
  /** When: the thinking or the answer is within a tenth of its budget. By default: mark; a key left out keeps its default. */
  budget_near: RuleSettings;
  /** When: another session's request reset the engine's conversation, so the next step reads it again. By default: mark; a key left out keeps its default. */
  engine_taken: RuleSettings;
  /** The most notes one rule sends the model in a row in a session, counted again from your own next message; after that the rule marks, pauses and tells the phone (decision 0053). */
  notes_in_a_row: number;
}

/** What Clank tells OpenCode of the model it works with (design 0012 §4.1, decision 0089). */
export interface OpenCodeSettings {
  /** The name clients show for this record; the file's own name when empty. */
  title: string;
  /** Tokens of the engine's window OpenCode is not told of, kept free for one step's tool results. OpenCode compacts a session once a step's total reaches the window it is told less its output limit; the step's tool results then go with the next request, which the engine refuses when it and the answer's room pass its window (262,144 less 16,384 less 16,384: OpenCode compacts at 229,376 tokens). The default holds one tool output as OpenCode cuts it (51,200 bytes or 2,000 lines) of code or prose, about 13,000 tokens; one of digits or a long listing can take up to 49,000, and several results in a step add up: then the gateway tells OpenCode the context was full, and OpenCode compacts. At most a quarter of the window is kept; 0 tells OpenCode the whole window. The Monitor shows the engine's window and the line OpenCode compacts at. */
  context_margin: number;
}

/** How the phone reaches Clank. */
export interface RemoteSettings {
  /** The name clients show for this record; the file's own name when empty. */
  title: string;
  /** Whether the phone page is published on your tailnet (decision 0012: off until you turn it on). */
  on: boolean;
  /** Where the phone's listener listens on this machine. */
  port: number;
  /** The HTTPS port Tailscale publishes the phone page on, on your tailnet only. */
  tailnet_port: number;
}

/** Clank's connection to Notion: where its API is, and which version of it Clank speaks. */
export interface NotionSettings {
  /** The name clients show for this record; the file's own name when empty. */
  title: string;
  /** Notion's API (another address only for a test). */
  api: string;
  /** The version of Notion's API Clank speaks (Notion-Version): 2025-09-03, in which a database holds data sources. */
  version: string;
}

/** A flow: boxes joined by lines, kept by workspace. */
export interface Flow {
  /** The name clients show for this record; the file's own name when empty. */
  title: string;
  /** The workspace whose folder its boxes work in; the folder it is kept in names it, and this, when given, must be the same. */
  workspace: string;
  defaults: FlowDefaults;
  /** Boxes the model proposes join the flow at once, when they pass the checks, up to the cap; off: each waits for you. */
  auto_accept: boolean;
  /** How many proposals auto-accept may accept in one run. */
  auto_accept_cap: number;
  /** Every box waits for you when it is done, to step through. */
  wait_after_every_box: boolean;
  /** Once its last gate is approved, the next flow is made from its INTEGRATE's brief: ask, you are asked whether to run it now; run, it starts at once; off, none is made. */
  next_flow: "ask" | "run" | "off";
  /** The flow it was made after, from that flow's INTEGRATE's brief. */
  follows: Follows | null;
  /** The flow made after it, from its INTEGRATE's brief: <workspace>/<name>. */
  next: string;
  /** A model that steers the run at checkpoints while it is on (design 0013 §16). */
  orchestrator: Orchestrator;
  /** Set when the model drafted it in a planning session and Clank wrote it: that session, when, and the brief written with the model. */
  built: Built | null;
  /** Its boxes; DECOMPOSE's tasks run in this order. */
  boxes: Box[];
  /** What comes after each box. */
  lines: Line[];
}

/** Who caused something: the user through a client, a paired device, an agent's session, a process, or Clank. */
export interface Actor {
  /** The user, a paired device, an agent's session, a process, or Clank itself. */
  kind: "user" | "device" | "session" | "process" | "clank";
  /** The client, device, session or process it came through, such as console. */
  via: string;
}

/** How a question was answered: the option or the words, who answered, through which client, and when. */
export interface Answer {
  /** The option chosen; none for an answer in words. */
  option: string | null;
  /** The answer in words, or a reason given with the option. */
  text: string;
  /** Who answered, and through which client. */
  by: Actor;
  /** When. */
  time: string;
}

/** What an option needs besides being chosen (decision 0114): a number in a unit, within bounds, on a step; the shape every client reads, `{"kind": "number", "unit", "min", "max", "step"}`. */
export interface Asked {
  /** number: an amount, a count, a size. */
  kind: "number";
  /** Its unit, such as USD. */
  unit: string;
  /** The least it may be. */
  min: number;
  /** The most it may be. */
  max: number;
  /** The least change it takes, such as 0.01; none: any. */
  step: number | null;
}

/** A step of a flow: a big task with a deliverable, done by a model in a session of its own, or the owner's. */
export interface Box {
  /** Its name in the flow's lines: letters, digits, '-' and '_'. */
  id: string;
  /** you: your brief or work; plan: a plan (PLAN.md); verify: a verdict on an earlier box's deliverable; decompose: proposed tasks; task: its deliverable; integrate: a summary of every deliverable and the next flow's brief; gate: your decision. */
  type: "you" | "plan" | "verify" | "decompose" | "task" | "integrate" | "gate";
  /** What it does, in a few words. */
  title: string;
  /** A VERIFY only: the earlier box whose deliverable it checks. */
  checks: string;
  /** The preset it runs on, by its id or title, loaded before it starts; empty: the flow's (a VERIFY's: the preset of the box it checks). */
  model: string;
  /** plan, review or auto, for its own session; empty: plan for PLAN, VERIFY, DECOMPOSE and INTEGRATE, the workspace's for a TASK. */
  mode: "plan" | "review" | "auto" | null;
  /** The files of the folder its first message hands it; it may still read any other. */
  sees: string[];
  /** A GATE's: the files it shows you, to approve or edit. */
  shows: string[];
  /** Its own words: yours, or drafted by a DECOMPOSE. */
  prompt: string;
  /** The files it must write in the folder; it is done when each was written during its try. */
  writes: string[];
  /** What its deliverable's files hold, in words. */
  holds: string;
  /** What makes its deliverable right, one thing per line, checked by a VERIFY or by you at a gate. */
  accept_when: string[];
  /** A command run in the workspace's container after it, which passes when it exits 0; empty: none. */
  accept_command: string;
  /** go on: the box after it starts; wait: the flow waits for you first. */
  when_done: "go on" | "wait";
  /** How many times it may run before a gate decides; empty: the flow's. */
  tries: number | null;
  /** What one try may use; empty values: the flow's. */
  limits: Limits;
  /** The workspace's MCP servers it gets; empty: those the workspace's agent gets. */
  mcp_servers: string[] | null;
  /** Where it came from, when it was accepted from a proposal. */
  proposed: Proposed | null;
}

/** How a flow built with the model came to be (design 0013 §15, decision 0097): the planning session its draft came from, when Clank wrote it, and the brief the owner wrote with the model, which its first box takes (decision 0098). */
export interface Built {
  /** The planning session the draft came from; empty when not known yet. */
  session: string;
  /** When Clank wrote the flow from the model's last draft. */
  at: string;
  /** The brief written with the model: its first box is done by it when it is there. */
  brief: string;
  /** The brief's fingerprint when the planning began (empty: not there): a brief still so is not the one written with the model, and its first box asks for it. */
  before: string;
}

/** The colors of the kinds of tool call, as the Monitor's flow draws them (design 0012 §6.3). */
export interface CallKinds {
  /** A call that reads (read, glob, grep, list). */
  reading: string;
  /** A call that runs a command (bash). */
  running: string;
  /** A call that changes a file (edit, write, patch). */
  editing: string;
  /** A call to an MCP server's tool. */
  mcp: string;
}

/** What one checkpoint of the orchestrator may use. */
export interface CheckpointLimits {
  /** How long one checkpoint may run. */
  minutes: number;
  /** How many tokens one checkpoint may write, its thinking included. */
  tokens: number;
}

/** The colors of the context's parts, as the Monitor draws them (design 0012 §4.2). */
export interface ContextParts {
  /** The agent program's instructions. */
  system: string;
  /** The tools the agent may call. */
  tools: string;
  /** What the owner wrote. */
  yours: string;
  /** What the model wrote as its answer. */
  text: string;
  /** The model's thinking sent back with the history. */
  thinking: string;
  /** The calls the model made. */
  calls: string;
  /** What the calls gave back. */
  results: string;
  /** Text that repeats itself, kept in the context. */
  loop: string;
}

/** The colors of a flow's kinds of box (design 0013 §12). */
export interface FlowBoxes {
  /** A brief, or work the owner does by hand. */
  you: string;
  /** A box that writes a plan. */
  plan: string;
  /** A box that checks an earlier box's deliverable. */
  verify: string;
  /** A box that breaks a plan into tasks. */
  decompose: string;
  /** A box that does one task. */
  task: string;
  /** A box that puts every deliverable together. */
  integrate: string;
  /** The owner's checkpoint. */
  gate: string;
}

/** What every box takes unless it names its own. */
export interface FlowDefaults {
  /** The preset each box runs on, by its id or title ("daily 262K"); empty: whatever the main slot runs when the box starts. */
  model: string;
  /** How many times a box may run before a gate decides (a VERIFY's loop). */
  tries: number;
  /** What one try of a box may use. */
  limits: FlowLimits;
  /** The bytes of a text file a box's first message hands whole; a larger one is named by its path and size, for the box to read with its tools. */
  whole_up_to: number;
  /** The characters of each earlier box's handoff note a box's first message hands; a longer note is cut there, saying where the whole is. */
  note_up_to: number;
  /** The bytes of a deliverable copied into the run's folder when its box ends; a larger one is kept by its fingerprint only. */
  copied_up_to: number;
}

/** What one try of a box may use, unless the box says otherwise. */
export interface FlowLimits {
  /** How long one try of a box may run. */
  minutes: number;
  /** How many tokens the model may write in one try, its thinking included (a prompt read again from the engine's cache is not counted). */
  tokens: number;
}

/** Where a next flow came from (design 0013 §3, decision 0091): the flow whose last gate was approved, its run, the INTEGRATE that wrote its brief, and the brief's file. */
export interface Follows {
  /** The flow it follows: <workspace>/<name>. */
  flow: string;
  /** That flow's run whose last gate was approved. */
  run: number;
  /** The INTEGRATE that wrote its brief. */
  by: string;
  /** The brief's file, copied into its own first box's file when it first runs. */
  brief: string;
  /** The fingerprint of its first box's file when it was made (empty: not in the folder): the brief is copied over it only while it is unchanged. */
  replaces: string;
}

/** One NVIDIA GPU, as `nvidia-smi` reports it. */
export interface Gpu {
  /** The GPU's model, such as NVIDIA GeForce RTX 5080. */
  name: string;
  /** Its memory, in mebibytes. */
  memory_mib: number;
  /** The version of the NVIDIA driver. */
  driver: string;
}

/** The configuration that last reached ready and answered (design 0001 §4.3). */
export interface LastGood {
  /** The preset's id. */
  preset: string;
  /** Its options then. */
  options: Record<string, unknown>;
  /** When it last reached ready. */
  time: string;
}

/** What one try of this box may use; each empty takes the flow's. */
export interface Limits {
  /** How long one try may run; empty: the flow's. */
  minutes: number | null;
  /** How many tokens the model may write in one try, its thinking included; empty: the flow's. */
  tokens: number | null;
}

/** What comes after a box: a then line, or a VERIFY's pass or fail line. */
export interface Line {
  /** The box it leaves. */
  from: string;
  /** The box it leads to. */
  to: string;
  /** A VERIFY's lines only: pass, to the box after it; fail, back to the box it checks, with the findings. */
  when: "pass" | "fail" | null;
}

/** One possible answer to a question, and what it does. */
export interface Option {
  /** How the answer names this option, such as stop. */
  id: string;
  /** The option as clients show it. */
  label: string;
  /** What choosing it does. */
  effect: string;
  /** The key that chooses it in the console, such as y. */
  key: string;
  /** What choosing it needs besides (decision 0114): a number, with its bounds and unit, given as the answer's words. */
  asks: Asked | null;
}

/** The model that steers a run at checkpoints while it is on (design 0013 §16, decisions 0123-0124): after each box a model ran, and at each question the run would ask you. */
export interface Orchestrator {
  /** Steer the run: a checkpoint after each box, and at each question; it decides as you would, within its limits, and you may answer first. */
  on: boolean;
  /** The preset its checkpoints run on, by its id or title; empty: the flow's. */
  model: string;
  /** steer: it decides the run's questions and may change the boxes ahead; watch: it checks each box is on track, goes on or pauses the run, and leaves every question to you. In both it tells you at once what you should know. */
  role: "steer" | "watch";
  /** Who decides the last gate: orchestrator, or owner (it waits for you). */
  final_review: "orchestrator" | "owner";
  /** How many changes it may make in one run: each box changed or added, send back, skip and extra try. */
  changes: number;
  /** How many tries past its cap it may give a box. */
  extra_tries: number;
  /** Checkpoints in a row without progress after which it may not go on: it changes the plan or stops. */
  stall: number;
  /** What one checkpoint may use. */
  limits: CheckpointLimits;
  /** What side tasks may use while a box waits on its job, and where their notes go. */
  side: SideLimits;
}

/** Where a box accepted from a proposal came from (design 0013 §9). */
export interface Proposed {
  /** The run in which it was proposed. */
  run: number;
  /** The box that proposed it, a DECOMPOSE above all. */
  by: string;
  /** owner: you accepted it; auto-accept: the flow's setting did, within its cap. */
  accepted: "owner" | "auto-accept";
}

/** What one Watch for rule does when it fires, and the words of its note (design 0012 §8). */
export interface RuleSettings {
  /** What the rule does when it fires: mark (the mark alone: on its node in the session's flow, in the Monitor's Watch for panel and beside Monitor in the menu), pause (the session, after its step), tell the phone (the phone page lists the mark with what waits), tell the model (a note in the rule's words, and the session goes on). A rule that does anything marks too; an empty list turns the rule off. */
  do: ("mark" | "pause" | "tell the phone" | "tell the model")[];
  /** What the model is told when the rule tells it, sent as a message of yours; {why} is replaced by what the mark rests on. */
  note: string;
}

/** What side work may use while a box waits on its job (design 0013 §17, decision 0132). */
export interface SideLimits {
  /** How long one side task may run. */
  minutes: number;
  /** How many tokens one side task may write, its thinking included. */
  tokens: number;
  /** How many side tasks one job's checkpoint may set going. */
  per_job: number;
  /** Minutes of side work in one run; past them a job's checkpoint may only wait or change. */
  budget: number;
  /** The folder, in the workspace's, where side tasks write their notes. */
  corpus: string;
}

/** One step of an operation, as it ran. */
export interface Step {
  /** Its place among the operation's steps, from 1. */
  number: number;
  /** What the step does, such as stop. */
  name: string;
  /** running, done, failed, or canceled (cut short by a cancel). */
  status: "running" | "done" | "failed" | "canceled";
  /** Whether running it again could do harm. */
  repeatable: boolean;
  /** When it started. */
  started: string;
  /** When it ended. */
  finished: string | null;
  /** Why it failed, when it did. */
  detail: string;
}

/** A bar's glyphs. */
export interface StyleBar {
  /** A bar's full cell. */
  full: string;
  /** A cell filled from none to seven eighths. */
  eighths: string;
  /** A bar's empty cell. */
  empty: string;
  /** The room a bar keeps for something (the answer, design 0012). */
  kept: string;
}

/** The colors by role: what each is for, never what it looks like. */
export interface StyleColors {
  /** The page, the panels and the windows. */
  background: string;
  /** The header and the keys bar. */
  bars: string;
  /** A diff or a command shown inside a panel. */
  inset: string;
  /** A button, a choice to pick. */
  surface: string;
  /** Every panel's border, the menu's edge, a divider. */
  border: string;
  /** The border of the panel that has the focus. */
  border_focused: string;
  /** A panel's title, set in its border. */
  title: string;
  /** A key, in the keys bar, the menu and a sentence. */
  key: string;
  /** The header's ◆ CLANK. */
  brand: string;
  /** The folder's name in the header, a workspace's in a sentence. */
  name: string;
  /** Text. */
  text: string;
  /** What explains: a time, a key's words, a panel's note. */
  quiet: string;
  /** The room kept for the answer, a list's rail, a waiting box's border. */
  dim: string;
  /** The highlighted row. */
  selection: string;
  /** The highlighted row's text, in bold. */
  selected_text: string;
  /** As wanted: running, ready, done. */
  good: string;
  /** Waits for you; a warning. */
  attention: string;
  /** What runs now; the spinner. */
  now: string;
  /** What failed, or is not as it should be. */
  failed: string;
  /** A page a later milestone brings. */
  planned: string;
  /** A bar below 60% of its whole. */
  low: string;
  /** A bar from 60% to 85% of its whole. */
  busy: string;
  /** A bar above 85% of its whole. */
  full: string;
  /** A diff's hunk line; added lines are good, removed failed. */
  diff_hunk: string;
  /** A scroll bar's thumb. */
  scrollbar: string;
  /** A scroll bar's track. */
  scrollbar_track: string;
  /** The ground of a button the mouse is over. */
  button_hover: string;
  /** The fill of the button that has the focus. */
  button_focused: string;
  /** A focused or pressed button's key and words, on its fill. */
  button_focused_text: string;
  /** A button's fill for the moment it is pressed. */
  button_pressed: string;
  /** The fill of a dimmed button that has the focus. */
  button_unable_focused: string;
}

/** The colors the Monitor and flows draw by kind, each by name, so a kind keeps its color. */
export interface StyleKinds {
  /** The context's parts. */
  parts: ContextParts;
  /** The kinds of tool call. */
  calls: CallKinds;
  /** A flow's kinds of box. */
  boxes: FlowBoxes;
}

/** The glyphs that say a state, and the others a page draws for a meaning. */
export interface StyleMarks {
  /** The header's mark before CLANK. */
  brand: string;
  /** Something that runs, or a state's dot. */
  on: string;
  /** Something that waits or is off. */
  off: string;
  /** Something done, or as wanted. */
  done: string;
  /** Something that failed. */
  failed: string;
  /** A question waiting. */
  asks: string;
  /** A line of history. */
  event: string;
  /** The end of text Clank cut to fit. */
  cut: string;
  /** A note of the owner's. */
  note: string;
  /** Something held: a model request, while its session is paused. */
  held: string;
}

/** The room between things, in cells. */
export interface StyleSpacing {
  /** Columns inside a panel's border. */
  panel_padding: number;
  /** Columns around a page. */
  page_padding: number;
  /** Rows between panels stacked. */
  rows_between: number;
  /** Columns between panels. */
  columns_between: number;
}

/** How a panel's title is set in its border. */
export interface StyleTitles {
  /** Where the title stands. */
  align: "left" | "center" | "right";
  /** Bold, or plain. */
  style: "bold" | "plain";
}

/** The connectors a branching flow is drawn with (design 0012 §6.3). */
export interface StyleTree {
  /** A line down. */
  down: string;
  /** A branch off a line down. */
  branch: string;
  /** The last branch. */
  last: string;
  /** A line across. */
  across: string;
  /** Where a line splits. */
  split: string;
  /** The last arm of a split. */
  split_end: string;
  /** Where lines join. */
  join: string;
  /** The last arm of a join. */
  join_end: string;
  /** Where a line leads. */
  arrow: string;
  /** A path not taken yet. */
  not_yet: string;
  /** Where a path ends. */
  dead_end: string;
}

/** The record an event or a question concerns. */
export interface Subject {
  /** The kind of that record, such as operation. */
  kind: string;
  /** That record's id. */
  id: string;
}

export interface RecordsByKind {
  service: ServiceSettings;
  console: ConsoleSettings;
  style: StyleSettings;
  event: Event;
  operation: Operation;
  question: Question;
  machine: MachineProfile;
  docker: DockerSettings;
  workspace: Workspace;
  preset: Preset;
  host: Host;
  "model-file": ModelFile;
  runtime: RuntimeSettings;
  endpoint: Endpoint;
  slot: SlotRecord;
  launch: LaunchRecord;
  install: InstallRecord;
  gateway: GatewaySettings;
  completion: CompletionSettings;
  vision: VisionSettings;
  cost: CostSettings;
  "mcp-server": McpServer;
  vscode: VsCodeSettings;
  monitor: MonitorSettings;
  opencode: OpenCodeSettings;
  remote: RemoteSettings;
  notion: NotionSettings;
  flow: Flow;
}
